<?php require_once 'config/config.php'; require_room();if(!in_array(room_role(),['chef','manager'],true)) {http_response_code(403);exit('Chef access required.');}$rid=room_id();$date=$_GET['date']??date('Y-m-d');$roomQ=db()->prepare('SELECT meal_times FROM rooms WHERE id=?');$roomQ->execute([$rid]);$sessions=(int)$roomQ->fetchColumn();$types=$sessions===3?['breakfast','lunch','dinner']:['lunch','dinner'];$counts=[];$people=[];$memberQ=db()->prepare("SELECT rm.user_id,u.name FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=? AND rm.status='active'");$memberQ->execute([$rid]);$all=$memberQ->fetchAll();foreach($types as $type){$counts[$type]=0;foreach($all as $person){$offQ=db()->prepare("SELECT status FROM meals WHERE room_id=? AND user_id=? AND meal_date=? AND meal_type=?");$offQ->execute([$rid,$person['user_id'],$date,$type]);$st=$offQ->fetchColumn();if($st!=='off'){$counts[$type]++;$people[]=['name'=>$person['name'],'meal_type'=>$type];}}}$title='Chef kitchen view';include 'includes/header.php';?><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold">Kitchen view</h2><p class="small-muted">Total meals to prepare for <?=e($date)?>.</p></div><form><input class="form-control" type="date" name="date" value="<?=e($date)?>" onchange="this.form.submit()"></form></div><div class="row g-3 mb-4"><?php foreach(['breakfast','lunch','dinner'] as $t):if(isset($counts[$t])):?><div class="col-md-4"><div class="card metric p-4"><div class="small-muted text-capitalize"><?=$t?></div><div class="display-5 fw-bold"><?=$counts[$t]?></div><div class="small-muted">meals to cook</div></div></div><?php endif;endforeach;?></div><div class="card p-4"><h5 class="fw-bold">Meal list</h5><div class="table-responsive"><table class="table"><thead><tr><th>Member</th><th>Meal</th></tr></thead><tbody><?php foreach($people as $p):?><tr><td><?=e($p['name'])?></td><td class="text-capitalize"><?=e($p['meal_type'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include 'includes/footer.php';?>